import{_ as a,a as t,o as i,ag as s}from"./chunks/framework.C2qfZH9T.js";const u=JSON.parse('{"title":"Extension Axepta BNP Paribas","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/installation.md","filePath":"getting-started/installation.md","lastUpdated":1782937842000}'),n={name:"getting-started/installation.md"};function l(o,e,r,p,d,h){return i(),t("div",null,e[0]||(e[0]=[s('<h1 id="extension-axepta-bnp-paribas" tabindex="-1">Extension Axepta BNP Paribas <a class="header-anchor" href="#extension-axepta-bnp-paribas" aria-label="Permalink to &quot;Extension Axepta BNP Paribas&quot;">​</a></h1><p>L&#39;extension <strong>Axepta BNP Paribas</strong> permet d&#39;intégrer la solution de paiement sécurisée Axepta à votre boutique Bagisto. Les clients sont redirigés vers la page de paiement sécurisée de BNP Paribas, garantissant un paiement conforme aux standards de sécurité PCI DSS et 3-D Secure.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>Après avoir copié le package dans votre projet Bagisto, exécutez la commande suivante :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> axepta:install</span></span></code></pre></div><p>L&#39;installateur :</p><ul><li>Publie les ressources du module.</li><li>Nettoie les caches de Bagisto.</li><li>Vérifie la configuration de l&#39;administration.</li><li>Rend le moyen de paiement disponible dans Bagisto.</li></ul><p>Une fois l&#39;installation terminée, videz les caches si nécessaire :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> optimize:clear</span></span></code></pre></div><hr><h1 id="fonctionnement" tabindex="-1">Fonctionnement <a class="header-anchor" href="#fonctionnement" aria-label="Permalink to &quot;Fonctionnement&quot;">​</a></h1><p>Lorsqu&#39;un client sélectionne <strong>Axepta BNP Paribas</strong> au moment du paiement :</p><ol><li>Une commande Bagisto est créée.</li><li>Les informations de paiement sont chiffrées à l&#39;aide de l&#39;algorithme Blowfish.</li><li>Une signature HMAC est générée.</li><li>Le client est redirigé vers la page de paiement sécurisée Axepta.</li><li>Après validation du paiement, Axepta redirige automatiquement le client vers votre boutique.</li><li>La notification serveur (URL Notify) met à jour automatiquement le statut de la commande.</li></ol><hr><h1 id="urls-de-retour" tabindex="-1">URLs de retour <a class="header-anchor" href="#urls-de-retour" aria-label="Permalink to &quot;URLs de retour&quot;">​</a></h1><p>Le module utilise automatiquement les URLs suivantes :</p><table tabindex="0"><thead><tr><th>Fonction</th><th>URL</th></tr></thead><tbody><tr><td>Paiement accepté</td><td><code>/axepta/success</code></td></tr><tr><td>Paiement refusé</td><td><code>/axepta/failure</code></td></tr><tr><td>Paiement annulé</td><td><code>/axepta/cancel</code></td></tr><tr><td>Notification serveur</td><td><code>/axepta/notify</code></td></tr></tbody></table><p>Ces URLs sont générées automatiquement par Bagisto.</p><hr><h1 id="compatibilite" tabindex="-1">Compatibilité <a class="header-anchor" href="#compatibilite" aria-label="Permalink to &quot;Compatibilité&quot;">​</a></h1><p>Le module est compatible avec :</p><ul><li>Bagisto 2.x</li><li>PHP 8.2+</li><li>PHP 8.3+</li><li>Laravel 11</li><li>Laravel 12</li></ul><hr><h1 id="securite" tabindex="-1">Sécurité <a class="header-anchor" href="#securite" aria-label="Permalink to &quot;Sécurité&quot;">​</a></h1><p>Le module implémente :</p><ul><li>Chiffrement Blowfish CBC</li><li>Signature HMAC SHA-256</li><li>Validation de la réponse Axepta</li><li>Gestion automatique des notifications serveur</li><li>Compatibilité 3-D Secure</li></ul><p>Aucune donnée bancaire n&#39;est stockée dans Bagisto. Toutes les informations de paiement sont traitées directement par la plateforme sécurisée Axepta BNP Paribas.</p><hr><h1 id="desinstallation" tabindex="-1">Désinstallation <a class="header-anchor" href="#desinstallation" aria-label="Permalink to &quot;Désinstallation&quot;">​</a></h1><p>Pour supprimer les ressources publiques du module :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> axepta:uninstall</span></span></code></pre></div><p>Ensuite, videz les caches :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> optimize:clear</span></span></code></pre></div>',33)]))}const m=a(n,[["render",l]]);export{u as __pageData,m as default};
